"""Virtual baselines: trivial predictors generated by the runner, not executed model apps.

They answer "what does a model with no knowledge of the text score?" on exactly the same
sample as the real apps. Class frequencies come from the task's *train* split; a task without one
falls back to uniform.
Test labels are never used to build the predictions.

    majority           Always the most frequent train label (ties: first label in the task's label order).
                       p_* = train class frequencies.
    stratified_random  A random label per article, drawn with the train class frequencies from a
                       generator seeded with the run seed (deterministic). p_* = one-hot of the draw,
                       as scikit-learn's DummyClassifier(strategy="stratified") does.
"""

from __future__ import annotations

import random
from pathlib import Path

import pandas as pd

import shared_path  # noqa: F401  (puts shared/ on sys.path)
import task as tasks

VIRTUAL = {
    "majority": {"title": "Majority class (virtual baseline)", "confidence": "train frequency of the majority label"},
    "stratified_random": {"title": "Stratified random (virtual baseline)", "confidence": "1.0 (one-hot random draw)"},
}


def class_prior(task: tasks.Task) -> tuple[dict[str, float], str]:
    """Label frequencies of the task's train split, and where they came from (uniform without one)."""
    labels = task.label_ids
    if "train" in task.files:
        counts = tasks.load_split(task, "train")["label"].value_counts()
        total = int(counts.sum())
        return {label: int(counts.get(label, 0)) / total for label in labels}, f"{task.name} train split ({total} articles)"
    return {label: 1 / len(labels) for label in labels}, f"uniform ({task.name} has no train split)"


def virtual_predictions(sample: pd.DataFrame, seed: int, task: tasks.Task | None = None) -> tuple[dict[str, pd.DataFrame], str]:
    """Predictions CSVs (standard columns) for every virtual baseline on this sample of texts."""
    task = task or tasks.load_task()
    labels = task.label_ids
    prior, source = class_prior(task)
    majority = max(labels, key=lambda label: (prior[label], -labels.index(label)))
    rng = random.Random(seed)
    draws = rng.choices(labels, weights=[prior[label] for label in labels], k=len(sample))

    base = sample[[c for c in ("sample_id", "text", "label") if c in sample.columns]].reset_index(drop=True)
    out = {}
    df = base.copy()
    df["pred"], df["confidence"] = majority, prior[majority]
    for label in labels:
        df[f"p_{label}"] = prior[label]
    out["majority"] = df

    df = base.copy()
    df["pred"], df["confidence"] = draws, 1.0
    for label in labels:
        df[f"p_{label}"] = [1.0 if d == label else 0.0 for d in draws]
    out["stratified_random"] = df
    return out, source


def write_virtual_baselines(run_dir: Path, sample: pd.DataFrame, seed: int, task: tasks.Task | None = None) -> dict[str, dict]:
    """Write each virtual baseline's CSV for the shared sample into the run folder; return summary.json entries."""
    task = task or tasks.load_task()
    frames, source = virtual_predictions(sample, seed, task)
    entries = {}
    for name, df in frames.items():
        dest = run_dir / "apps" / f"virtual_{name}"
        dest.mkdir(parents=True, exist_ok=True)
        csv = dest / f"predictions_{tasks.result_stem(task, len(sample), seed)}.csv"
        df.to_csv(csv, index=False)
        entries[f"virtual_{name}"] = {
            **VIRTUAL[name], "runs_on": "Virtual baseline (no model)", "supervision": "virtual",
            "virtual": True, "status": "virtual",
            "reason": f"generated by the runner from the shared sample; class frequencies: {source}; seed {seed}",
            "csv": str(csv.relative_to(run_dir)),
        }
    return entries
